def go(n, page, src, mid, small, tid, tname, diff, ans, chk, pts, fmt, ex):
    ex = dict(ex); rv = ex.pop("rv", 0)
    kw = {k: v for k, v in ex.items()}
    kw["atype"] = "선택지" if fmt == MC else "값"
    note = "원본 PDF 내 사용자 체크(✔/숫자) 표기와 일치(표기는 정답지 아님)"
    if rv:
        note = "인쇄 체크 표기값 기록 — 독립 완전풀이 미완료(RECHECK 대상); " + note
        kw["review"] = "REVIEW-정답지미연결;RECHECK-독립풀이미완"
    R(QB + n, page, BIG, mid, small, tid, tname, BIG, diff, fmt, ans, f"원출처 {src}번", (chk + "; " if chk else "") + note, label=f"{CH}-{n:03d}", pts=str(pts), **kw)
    r = ROWS[-1]; r.update({"출처대분류": "시판 기출문제집(평가원·교육청 기출 재수록)", "학교명": "", "학교/시험명": f"수능기출올픽 미적분 BOOK1 {CH} — {src}번",
        "메모": r["메모"].replace("P1 학교기출", "P1 시판 기출문제집; 원출처 평가원/교육청 문항(OFFICIAL 스트림과 근접중복 가능)")})
